//! Protocol core of QOP Desktop, shared by the app binary and its tests.
//!
//! `wire` and `registry` are pure ports of the TS identity/protocol subset a
//! linked device needs. TypeScript stays the source of truth: the golden
//! vectors in `tests/vectors` (generated by `cli/scripts/desktop-vectors.ts`)
//! pin both implementations to the same bytes and the same accept/reject
//! decisions.
//!
//! Around them: `config` (endpoints), `store` and `keys` (local state and the
//! device key) and `node` (the minip2p thread).

pub mod config;
pub mod keys;
pub mod node;
pub mod registry;
pub mod store;
pub mod wire;
